<template>
  <section class="platform-data">
    <header class="page-header">
      <div><p class="eyebrow">PLATFORM DATA · LOCAL METRICS</p><h1>平台数据</h1><p class="subtitle">查看已回写内容指标的表现，区分累计快照、平台分布和可继续优化的内容。</p></div>
      <div class="header-actions"><el-button :loading="loading" @click="load">刷新数据</el-button><el-button @click="metricDialog = true">录入指标</el-button><el-button @click="batchDialog = true">批量导入快照</el-button><el-button @click="credentialDialog = true">管理平台接入</el-button><el-button type="primary" @click="router.push('/content')">进入内容中心</el-button></div>
    </header>

    <el-alert type="info" :closable="false" show-icon class="notice">平台数据来自人工回写快照或已注册连接器的真实公开指标；未接入平台连接器时，不会伪造实时抖音、公众号或知乎数据。</el-alert>

    <el-card shadow="never" class="connection-card">
      <template #header><div class="card-heading"><div><span class="section-kicker">CONNECTOR HEALTH</span><h2>平台连接状态</h2></div><el-tag effect="plain">{{ activeCredentials.length }} 个凭据</el-tag></div></template>
      <div class="connector-grid">
        <article v-for="connector in connectorCards" :key="connector.key" class="connector-item">
          <div class="connector-topline"><span class="platform-badge">{{ connector.label.slice(0, 1) }}</span><div><h3>{{ connector.label }}</h3><small>{{ connector.detail }}</small></div><el-tag size="small" :type="connector.tagType">{{ connector.statusLabel }}</el-tag></div>
          <p>{{ connector.description }}</p>
          <div class="connector-actions"><el-button v-if="connector.requiresCredentials" size="small" type="primary" plain @click="openCredential(connector.key)">配置凭据</el-button><el-button v-if="connector.supportsMetricSync && connector.credentialCount" size="small" type="success" plain :loading="syncingPlatform === connector.key" @click="syncPlatformMetrics(connector.key)">同步真实指标</el-button><el-button v-if="connector.key === 'manual'" size="small" plain @click="router.push('/content')">去确认发布</el-button><span v-if="connector.credentialCount" class="credential-count">{{ connector.credentialCount }} 个凭据已保存</span></div>
        </article>
      </div>
    </el-card>

    <div class="metric-grid">
      <div class="metric-card"><span>公开作品</span><strong>{{ overview?.content_performance.publish_count || 0 }}</strong><small>人工确认发布记录</small></div>
      <div class="metric-card accent"><span>累计曝光</span><strong>{{ formatNumber(overview?.content_performance.impressions) }}</strong><small>已回写指标快照</small></div>
      <div class="metric-card"><span>累计点击</span><strong>{{ formatNumber(overview?.content_performance.clicks) }}</strong><small>整体点击率 {{ percentage(overview?.content_performance.click_through_rate) }}</small></div>
      <div class="metric-card"><span>互动总量</span><strong>{{ formatNumber(interactions) }}</strong><small>赞、评、转发合计</small></div>
    </div>

    <div class="analysis-grid">
      <el-card shadow="never" class="trend-card"><template #header><div class="card-heading"><div><span class="section-kicker">PERFORMANCE TREND</span><h2>指标趋势</h2></div><el-tag effect="plain">{{ trendRows.length ? `${trendRows.length} 个采集日` : '暂无快照' }}</el-tag></div></template><div v-if="trendRows.length" class="trend-chart"><div v-for="row in trendRows" :key="row.date" class="trend-column"><div class="trend-bars"><span class="trend-bar impressions" :style="{ height: `${barHeight(row.impressions)}%` }" :title="`曝光 ${formatNumber(row.impressions)}`" /><span class="trend-bar clicks" :style="{ height: `${barHeight(row.clicks)}%` }" :title="`点击 ${formatNumber(row.clicks)}`" /><span class="trend-bar interactions" :style="{ height: `${barHeight(row.interactions)}%` }" :title="`互动 ${formatNumber(row.interactions)}`" /></div><small>{{ row.label }}</small></div></div><el-empty v-else description="导入至少两次指标快照后，这里会显示真实趋势" :image-size="64" /></el-card>
      <el-card shadow="never" class="leaderboard-card"><template #header><div class="card-heading"><div><span class="section-kicker">CONTENT RANKING</span><h2>快照表现排行</h2></div><el-tag effect="plain">{{ topMetricRows.length }} 条</el-tag></div></template><div v-if="topMetricRows.length" class="leaderboard-list"><div v-for="(row, index) in topMetricRows" :key="row.publish_record_id" class="leaderboard-row"><b>{{ String(index + 1).padStart(2, '0') }}</b><div><strong>{{ platformLabel(row.platform) }} · {{ formatDate(row.collected_at) }}</strong><small>曝光 {{ formatNumber(row.impressions) }} · 点击 {{ formatNumber(row.clicks) }} · 互动 {{ formatNumber(row.interactions) }}</small></div><el-tag size="small" :type="row.ctr >= 0.05 ? 'success' : 'info'">CTR {{ percentage(row.ctr) }}</el-tag></div></div><el-empty v-else description="还没有可排行的指标快照" :image-size="64" /></el-card>
    </div>

    <el-card v-if="syncRuns.length" shadow="never" class="sync-card"><template #header><div class="card-heading"><div><span class="section-kicker">SYNC RUNS</span><h2>指标同步任务</h2></div><el-tag effect="plain">{{ syncRuns.length }} 条</el-tag></div></template><div class="sync-list"><div v-for="run in syncRuns" :key="run.id" class="sync-row"><div><strong>{{ platformLabel(run.platform) }} 指标快照</strong><small>{{ formatDate(run.created_at) }} · {{ run.inserted }} 条写入 · {{ run.skipped }} 条跳过</small></div><el-tag :type="syncStatusType(run.status)">{{ syncStatusLabel(run.status) }}</el-tag><span v-if="run.error_message" class="sync-error">{{ run.error_message }}</span><el-button v-if="run.status === 'failed'" size="small" type="warning" plain :loading="retryingSyncId === run.id" @click="retrySync(run.id)">重试</el-button></div></div></el-card>

    <el-card shadow="never" class="filter-card"><div class="filter-row"><el-input v-model="keyword" clearable placeholder="搜索平台或内容状态" /><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option label="已发布" value="published" /><el-option label="待确认" value="pending" /><el-option label="失败" value="failed" /></el-select><el-button @click="resetFilters">重置</el-button></div></el-card>

    <div class="content-grid">
      <el-card shadow="never" class="platform-card"><template #header><div class="card-heading"><div><span class="section-kicker">CHANNEL OVERVIEW</span><h2>平台表现</h2></div><el-tag effect="plain">{{ platformRows.length }} 个平台</el-tag></div></template><div v-if="filteredPlatformRows.length" class="platform-list"><article v-for="item in filteredPlatformRows" :key="item.platform" class="platform-item"><div class="platform-title"><span class="platform-badge">{{ platformLabel(item.platform).slice(0, 1) }}</span><div><h3>{{ platformLabel(item.platform) }}</h3><small>{{ item.count }} 条发布记录 · {{ item.statusLabel }}</small></div><el-tag :type="item.ctr >= 0.05 ? 'success' : 'info'">CTR {{ percentage(item.ctr) }}</el-tag></div><div class="platform-stats"><div><span>曝光</span><strong>{{ formatNumber(item.impressions) }}</strong></div><div><span>点击</span><strong>{{ formatNumber(item.clicks) }}</strong></div><div><span>互动</span><strong>{{ formatNumber(item.interactions) }}</strong></div></div><el-progress :percentage="Math.min(100, Math.round(item.ctr * 1000))" :show-text="false" :stroke-width="8" /></article></div><el-empty v-else description="暂无匹配的平台指标" :image-size="72" /></el-card>

      <el-card shadow="never" class="insight-card"><template #header><div class="card-heading"><div><span class="section-kicker">OPTIMIZATION NOTES</span><h2>优化提示</h2></div></div></template><div class="note-list"><div><b>01</b><span><strong>先补齐平台连接</strong><small>当前数据是人工回写快照，接入平台凭据后再开启自动采集。</small></span></div><div><b>02</b><span><strong>优先复盘高点击内容</strong><small>点击率高于 5% 的内容适合沉淀为可复用选题模板。</small></span></div><div><b>03</b><span><strong>回到内容中心行动</strong><small>可直接改写、排期、确认发布或生成复盘报告。</small></span></div></div><el-button class="full-button" @click="router.push('/content')">查看内容与复盘</el-button></el-card>
    </div>

    <el-card shadow="never" class="recent-card"><template #header><div class="card-heading"><div><span class="section-kicker">RECENT SNAPSHOT</span><h2>最近发布快照</h2></div><el-button link type="primary" @click="router.push('/content')">查看内容中心</el-button></div></template><el-table :data="filteredPublishes" empty-text="暂无发布快照"><el-table-column prop="platform" label="平台" min-width="140"><template #default="{ row }">{{ platformLabel(row.platform) }}</template></el-table-column><el-table-column prop="status" label="状态" width="120"><template #default="{ row }"><el-tag size="small" :type="row.status === 'published' ? 'success' : 'info'">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column prop="published_at" label="时间" min-width="180" /><el-table-column label="曝光 / 点击" min-width="160"><template #default="{ row }">{{ formatNumber(metric(row, 'impressions')) }} / {{ formatNumber(metric(row, 'clicks')) }}</template></el-table-column><el-table-column label="互动" min-width="120"><template #default="{ row }">{{ formatNumber(metric(row, 'likes') + metric(row, 'comments') + metric(row, 'shares')) }}</template></el-table-column></el-table></el-card>

    <el-dialog v-model="credentialDialog" title="配置平台凭据" width="560px" destroy-on-close>
      <el-alert type="warning" :closable="false" show-icon class="dialog-warning">凭据会加密保存；只有后端已注册的连接器才能自动发布或同步。X 连接器支持真实公开指标同步，未注册平台仍需人工发布并导入快照。</el-alert>
      <div v-if="credentialForm.platform === 'x'" class="oauth-action"><el-button type="primary" plain :loading="startingXOAuth" @click="startXOAuth">使用 X OAuth 授权</el-button><small>需要后端配置 X Client ID、回调地址和 PKCE；未配置时会明确提示，不会伪造授权成功。</small></div>
      <el-form label-position="top" class="credential-form">
        <el-form-item label="平台"><el-select v-model="credentialForm.platform" placeholder="选择平台" style="width:100%"><el-option label="抖音" value="douyin" /><el-option label="公众号" value="wechat" /><el-option label="X / 短帖" value="x" /><el-option label="知乎" value="zhihu" /><el-option label="网站" value="website" /></el-select></el-form-item>
        <el-form-item label="凭据名称"><el-input v-model="credentialForm.name" placeholder="例如：品牌官方账号" /></el-form-item>
        <el-form-item label="安全提示"><el-input v-model="credentialForm.hint" placeholder="例如：生产账号 / 只读权限" /></el-form-item>
        <el-form-item label="凭据 JSON"><el-input v-model="credentialForm.json" type="textarea" :rows="5" placeholder='例如：{"access_token":"..."}' /></el-form-item>
      </el-form>
      <div class="saved-credentials">
        <div class="saved-heading"><strong>已保存凭据</strong><span>只显示名称和安全提示，不展示密钥内容</span></div>
        <div v-if="credentials.length" class="saved-list"><div v-for="credential in credentials" :key="credential.id" class="saved-row"><span class="platform-badge small">{{ platformLabel(credential.platform).slice(0, 1) }}</span><span class="saved-main"><strong>{{ credential.name }}</strong><small>{{ platformLabel(credential.platform) }} · {{ credential.credential_hint || '已加密保存' }}</small></span><el-tag size="small" type="success">{{ credential.status === 'active' ? '启用' : credential.status }}</el-tag><el-button v-if="credential.status === 'active'" link type="primary" :loading="testingId === credential.id" @click="testCredential(credential.id)">测试连接</el-button><el-button link type="danger" :loading="revokingId === credential.id" @click="revokeCredential(credential.id)">撤销</el-button></div></div>
        <el-empty v-else description="还没有保存的平台凭据" :image-size="52" />
      </div>
      <template #footer><el-button @click="credentialDialog = false">取消</el-button><el-button type="primary" :loading="savingCredential" @click="saveCredential">保存凭据</el-button></template>
    </el-dialog>

    <el-dialog v-model="metricDialog" title="回写平台指标" width="620px" destroy-on-close>
      <el-alert type="info" :closable="false" show-icon class="dialog-warning">支持手工回写或从平台后台复制的快照；每次保存都会更新平台汇总和内容复盘数据。已注册真实连接器的平台可直接在上方同步。</el-alert>
      <el-form label-position="top" class="metric-form">
        <el-form-item label="发布记录"><el-select v-model="metricForm.publishId" filterable placeholder="选择一条发布记录" style="width:100%"><el-option v-for="publish in publishes" :key="publish.id" :label="`${platformLabel(publish.platform)} · ${formatDate(publish.published_at)}`" :value="publish.id" /></el-select></el-form-item>
        <div class="metric-input-grid"><el-form-item label="曝光"><el-input-number v-model="metricForm.impressions" :min="0" :step="100" controls-position="right" /></el-form-item><el-form-item label="点击"><el-input-number v-model="metricForm.clicks" :min="0" :step="10" controls-position="right" /></el-form-item><el-form-item label="点赞"><el-input-number v-model="metricForm.likes" :min="0" :step="10" controls-position="right" /></el-form-item><el-form-item label="评论"><el-input-number v-model="metricForm.comments" :min="0" :step="1" controls-position="right" /></el-form-item><el-form-item label="分享"><el-input-number v-model="metricForm.shares" :min="0" :step="1" controls-position="right" /></el-form-item></div>
      </el-form>
      <template #footer><el-button @click="metricDialog = false">取消</el-button><el-button type="primary" :loading="savingMetric" @click="saveMetric">保存指标</el-button></template>
    </el-dialog>

    <el-dialog v-model="batchDialog" title="批量导入指标快照" width="680px" destroy-on-close>
      <el-alert type="info" :closable="false" show-icon class="dialog-warning">支持从平台后台复制的 JSON 或 CSV 快照。CSV 表头使用 publish_id、collected_at、impressions、clicks、likes、comments、shares；相同发布记录与采集时间不会重复写入。</el-alert>
      <el-form label-position="top"><el-form-item label="快照来源平台"><el-select v-model="batchPlatform" placeholder="选择平台" style="width:100%"><el-option label="人工快照" value="manual" /><el-option label="抖音" value="douyin" /><el-option label="公众号" value="wechat" /><el-option label="X / 短帖" value="x" /><el-option label="知乎" value="zhihu" /><el-option label="网站" value="website" /></el-select></el-form-item><el-form-item label="导入格式"><el-radio-group v-model="batchFormat"><el-radio-button value="json">JSON</el-radio-button><el-radio-button value="csv">CSV</el-radio-button></el-radio-group></el-form-item></el-form>
      <el-input v-model="batchJson" type="textarea" :rows="12" class="batch-input" :placeholder="batchPlaceholder" />
      <div class="batch-tools">
        <label class="file-picker">
          <input type="file" accept=".csv,.json,text/csv,application/json" @change="handleBatchFile" />
          <span>从文件读取快照</span>
        </label>
        <el-button link type="primary" @click="downloadBatchTemplate">下载 CSV 模板</el-button>
        <span>文件只在浏览器中读取，提交前仍会按当前格式校验。</span>
      </div>
      <template #footer><el-button @click="batchDialog = false">取消</el-button><el-button type="primary" :loading="importingBatch" @click="importBatch">导入快照</el-button></template>
    </el-dialog>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { contentApi } from '@/api/content'
import { dataCenterApi, type DataCenterOverview } from '@/api/dataCenter'
import { useWorkspaceStore } from '@/stores/workspace'
import type { ContentMetricSyncRun, ContentPublishRecord } from '@/types/content'

const router = useRouter(); const route = useRoute(); const workspaceStore = useWorkspaceStore(); const loading = ref(false); const overview = ref<DataCenterOverview | null>(null); const publishes = ref<ContentPublishRecord[]>([]); const metrics = ref<Array<{ id: string; publish_record_id: string; workspace_id: string; published_at: string; collected_at: string; impressions: number; clicks: number; likes: number; comments: number; shares: number; platform: string }>>([]); const syncRuns = ref<ContentMetricSyncRun[]>([]); const keyword = ref(''); const statusFilter = ref(''); const connectors = ref<Array<{ key: string; label: string; status: string; requires_credentials?: boolean; supports_metric_sync?: boolean }>>([]); const credentials = ref<Array<{ id: string; platform: string; name: string; credential_hint: string; status: string }>>([]); const credentialDialog = ref(false); const savingCredential = ref(false); const startingXOAuth = ref(false); const revokingId = ref(''); const testingId = ref(''); const retryingSyncId = ref(''); const syncingPlatform = ref(''); const credentialForm = ref({ platform: '', name: '', hint: '', json: '' }); const metricDialog = ref(false); const savingMetric = ref(false); const metricForm = ref({ publishId: '', impressions: 0, clicks: 0, likes: 0, comments: 0, shares: 0 }); const batchDialog = ref(false); const importingBatch = ref(false); const batchPlatform = ref('manual'); const batchFormat = ref<'json' | 'csv'>('json'); const batchJson = ref('')
const metric = (row: ContentPublishRecord, key: string) => Number(row.latest_metrics?.[key] || 0)
const interactions = computed(() => Number(overview.value?.content_performance.likes || 0) + Number(overview.value?.content_performance.comments || 0) + Number(overview.value?.content_performance.shares || 0))
const platformRows = computed(() => { const groups = new Map<string, { platform: string; count: number; impressions: number; clicks: number; interactions: number; statusLabel: string }>(); publishes.value.forEach(row => { const current = groups.get(row.platform) || { platform: row.platform, count: 0, impressions: 0, clicks: 0, interactions: 0, statusLabel: '已发布' }; current.count += 1; current.impressions += metric(row, 'impressions'); current.clicks += metric(row, 'clicks'); current.interactions += metric(row, 'likes') + metric(row, 'comments') + metric(row, 'shares'); current.statusLabel = statusLabel(row.status); groups.set(row.platform, current) }); return [...groups.values()].map(item => ({ ...item, ctr: item.impressions ? item.clicks / item.impressions : 0 })) })
const filteredPlatformRows = computed(() => platformRows.value.filter(item => { const text = `${platformLabel(item.platform)} ${item.statusLabel}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!statusFilter.value || item.statusLabel === statusLabel(statusFilter.value)) }))
const filteredPublishes = computed(() => publishes.value.filter(row => { const text = `${platformLabel(row.platform)} ${statusLabel(row.status)}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!statusFilter.value || row.status === statusFilter.value) }).slice(0, 20))
const trendRows = computed(() => { const groups = new Map<string, { date: string; label: string; impressions: number; clicks: number; interactions: number }>(); metrics.value.forEach(item => { const date = new Date(item.collected_at); if (Number.isNaN(date.getTime())) return; const key = date.toISOString().slice(0, 10); const current = groups.get(key) || { date: key, label: `${date.getMonth() + 1}/${date.getDate()}`, impressions: 0, clicks: 0, interactions: 0 }; current.impressions += Number(item.impressions || 0); current.clicks += Number(item.clicks || 0); current.interactions += Number(item.likes || 0) + Number(item.comments || 0) + Number(item.shares || 0); groups.set(key, current) }); return [...groups.values()].sort((a, b) => a.date.localeCompare(b.date)).slice(-14) })
const trendMax = computed(() => Math.max(1, ...trendRows.value.map(row => row.impressions)))
const topMetricRows = computed(() => { const latest = new Map<string, typeof metrics.value[number]>(); [...metrics.value].sort((a, b) => new Date(b.collected_at).getTime() - new Date(a.collected_at).getTime()).forEach(item => { if (!latest.has(item.publish_record_id)) latest.set(item.publish_record_id, item) }); return [...latest.values()].map(item => ({ ...item, interactions: Number(item.likes || 0) + Number(item.comments || 0) + Number(item.shares || 0), ctr: Number(item.impressions || 0) ? Number(item.clicks || 0) / Number(item.impressions || 0) : 0 })).sort((a, b) => b.impressions - a.impressions).slice(0, 5) })
const batchPlaceholder = computed(() => batchFormat.value === 'csv' ? 'publish_id,collected_at,impressions,clicks,likes,comments,shares\npublish-uuid,2026-08-05T12:00:00Z,1000,80,30,4,2' : '例如：[{"publish_id":"发布记录 ID","collected_at":"2026-08-05T12:00:00Z","metric":{"impressions":1000,"clicks":80,"likes":30,"comments":4,"shares":2}}]')
const activeCredentials = computed(() => credentials.value.filter(item => item.status === 'active'))
const connectorCards = computed(() => {
  const known = new Map(connectors.value.map(item => [item.key, item]))
  const keys = ['manual', 'douyin', 'wechat', 'x', 'zhihu', 'website']
  return keys.map(key => {
    const item = known.get(key)
    const credentialCount = activeCredentials.value.filter(credential => credential.platform === key).length
    if (item) {
      const pending = item.status === 'pending_adapter'
      return { key, label: item.label, requiresCredentials: Boolean(item.requires_credentials), supportsMetricSync: Boolean(item.supports_metric_sync), credentialCount, statusLabel: pending ? (credentialCount ? '凭据已保存' : '待适配器') : item.requires_credentials ? (credentialCount ? '已配置' : '待配置') : '可用', tagType: (pending || (item.requires_credentials && !credentialCount) ? 'warning' : 'success') as 'warning' | 'success', detail: pending ? (credentialCount ? `${credentialCount} 个凭据 · 尚未注册自动连接器` : '尚未注册自动连接器') : item.requires_credentials ? `${credentialCount} 个凭据 · 连接器状态 ${item.status}` : '人工确认发布', description: pending ? '当前可以保存凭据，但自动发布与实时同步仍需后端适配器。' : item.supports_metric_sync ? '可读取已发布内容的真实公开指标，并写入平台趋势。' : item.requires_credentials ? '配置凭据后才能启用自动发布或平台同步。' : '发布后由人工确认，并在内容中心回写指标。' }
    }
    return { key, label: platformLabel(key), requiresCredentials: true, supportsMetricSync: false, credentialCount, statusLabel: credentialCount ? '凭据已保存' : '待适配器', tagType: (credentialCount ? 'info' : 'warning') as 'info' | 'warning', detail: credentialCount ? `${credentialCount} 个凭据 · 尚未注册自动连接器` : '尚未注册自动连接器', description: '当前可以保存凭据，但自动发布与实时同步仍需后端适配器。' }
  })
})
function formatNumber(value?: number | null) { return new Intl.NumberFormat('zh-CN').format(Number(value || 0)) }
function formatDate(value?: string | null) { return value ? new Date(value).toLocaleString('zh-CN') : '未记录时间' }
function percentage(value?: number | null) { return `${(Number(value || 0) * 100).toFixed(1)}%` }
function platformLabel(platform: string) { return ({ douyin: '抖音', wechat: '公众号', website: '网站', x: 'X / 短帖', zhihu: '知乎', manual: '人工发布' } as Record<string, string>)[platform] || platform }
function statusLabel(status: string) { return ({ published: '已发布', pending: '待确认', failed: '失败' } as Record<string, string>)[status] || status }
function syncStatusLabel(status: string) { return ({ queued: '排队中', running: '同步中', completed: '已完成', failed: '失败', retrying: '重试中' } as Record<string, string>)[status] || status }
function syncStatusType(status: string) { return status === 'completed' ? 'success' : status === 'failed' ? 'danger' : 'warning' }
function resetFilters() { keyword.value = ''; statusFilter.value = '' }
function barHeight(value: number) { return Math.max(4, Math.round((Number(value || 0) / trendMax.value) * 100)) }
function openCredential(platform: string) { credentialForm.value.platform = platform; credentialDialog.value = true }
async function handleBatchFile(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; try { batchJson.value = await file.text(); batchFormat.value = file.name.toLowerCase().endsWith('.csv') ? 'csv' : 'json'; ElMessage.success(`已读取 ${file.name}`) } catch { ElMessage.error('读取快照文件失败') } finally { input.value = '' } }
function downloadBatchTemplate() { const csv = 'publish_id,collected_at,impressions,clicks,likes,comments,shares\n发布记录 ID,2026-08-05T12:00:00Z,1000,80,30,4,2\n'; const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'platform-metrics-template.csv'; anchor.click(); URL.revokeObjectURL(url) }
async function revokeCredential(id: string) { revokingId.value = id; try { await contentApi.revokeCredential(id); ElMessage.success('凭据已撤销'); await load() } catch (error) { ElMessage.error(error instanceof Error ? error.message : '凭据撤销失败') } finally { revokingId.value = '' } }
async function testCredential(id: string) { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId) return; testingId.value = id; try { const result = await contentApi.testCredential(id, workspaceId); if (result.status === 'not_supported') ElMessage.warning(result.message); else ElMessage.success(result.message) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '连接测试失败') } finally { testingId.value = '' } }
async function syncPlatformMetrics(platform: string) { const workspaceId = workspaceStore.currentWorkspaceId; const credential = activeCredentials.value.find(item => item.platform === platform); if (!workspaceId || !credential) return ElMessage.warning('请先配置并启用平台凭据'); syncingPlatform.value = platform; try { const run = await contentApi.createMetricSync({ workspace_id: workspaceId, platform, credential_id: credential.id, items: [] }); ElMessage.success('真实指标同步任务已提交'); await load(); await pollSync(run.id) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '真实指标同步失败') } finally { syncingPlatform.value = '' } }
async function startXOAuth() { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId) return ElMessage.warning('当前没有可用工作空间'); startingXOAuth.value = true; try { const result = await contentApi.startXOAuth(workspaceId); window.location.assign(result.url) } catch (error) { ElMessage.error(error instanceof Error ? error.message : 'X OAuth 尚未配置或启动失败') } finally { startingXOAuth.value = false } }
async function completeXOAuthFromQuery() { const code = String(route.query.code || ''); const state = String(route.query.state || ''); if (!code || !state) return; try { const result = await contentApi.completeXOAuth({ code, state }); ElMessage.success(`X OAuth 已授权：${result.provider_user_id}`); credentialDialog.value = true; credentialForm.value.platform = 'x'; await router.replace({ query: {} }) } catch (error) { ElMessage.error(error instanceof Error ? error.message : 'X OAuth 回调处理失败'); await router.replace({ query: {} }) } }
async function saveMetric() { if (!metricForm.value.publishId) return ElMessage.warning('请选择一条发布记录'); savingMetric.value = true; try { await contentApi.addMetric(metricForm.value.publishId, { impressions: metricForm.value.impressions, clicks: metricForm.value.clicks, likes: metricForm.value.likes, comments: metricForm.value.comments, shares: metricForm.value.shares }); metricDialog.value = false; metricForm.value = { publishId: '', impressions: 0, clicks: 0, likes: 0, comments: 0, shares: 0 }; ElMessage.success('指标快照已回写'); await load() } catch (error) { ElMessage.error(error instanceof Error ? error.message : '指标回写失败') } finally { savingMetric.value = false } }
function parseMetricCsv(value: string) { const rows = value.trim().split(/\r?\n/).filter(Boolean); if (rows.length < 2) throw new Error('CSV 至少需要表头和一条数据'); const headers = rows.shift()!.split(',').map(item => item.trim()); const required = ['publish_id', 'collected_at', 'impressions', 'clicks', 'likes', 'comments', 'shares']; const missing = required.filter(item => !headers.includes(item)); if (missing.length) throw new Error(`CSV 缺少字段：${missing.join('、')}`); return rows.map((row, index) => { const values = row.split(',').map(item => item.trim()); const data = Object.fromEntries(headers.map((header, column) => [header, values[column] || ''])); if (!data.publish_id || !data.collected_at) throw new Error(`CSV 第 ${index + 2} 行缺少 publish_id 或 collected_at`); return { publish_id: data.publish_id, collected_at: data.collected_at, metric: { impressions: Number(data.impressions || 0), clicks: Number(data.clicks || 0), likes: Number(data.likes || 0), comments: Number(data.comments || 0), shares: Number(data.shares || 0) } } }) }
async function importBatch() { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId || !batchJson.value.trim()) return ElMessage.warning(`请粘贴${batchFormat.value.toUpperCase()}快照`); let items: Array<{ publish_id: string; collected_at: string; metric: Record<string, unknown> }>; try { if (batchFormat.value === 'csv') items = parseMetricCsv(batchJson.value); else { const parsed = JSON.parse(batchJson.value); if (!Array.isArray(parsed) || !parsed.length) throw new Error('快照必须是非空数组'); items = parsed } } catch (error) { return ElMessage.error(error instanceof Error ? error.message : '快照格式不正确') } importingBatch.value = true; try { const run = await contentApi.createMetricSync({ workspace_id: workspaceId, platform: batchPlatform.value, items }); batchDialog.value = false; batchJson.value = ''; batchFormat.value = 'json'; ElMessage.success('指标同步任务已提交，可在页面查看处理状态'); await load(); await pollSync(run.id) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '批量同步失败') } finally { importingBatch.value = false } }
async function pollSync(runId: string) { for (let attempt = 0; attempt < 10; attempt += 1) { await new Promise(resolve => window.setTimeout(resolve, 800)); try { const run = await contentApi.getMetricSync(runId); const index = syncRuns.value.findIndex(item => item.id === run.id); if (index >= 0) syncRuns.value[index] = run; else syncRuns.value.unshift(run); if (['completed', 'failed'].includes(run.status)) { await load(); return } } catch { return } } }
async function retrySync(runId: string) { retryingSyncId.value = runId; try { const run = await contentApi.retryMetricSync(runId); ElMessage.success('已重新提交同步任务'); await load(); await pollSync(run.id) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '同步重试失败') } finally { retryingSyncId.value = '' } }
async function saveCredential() { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId || !credentialForm.value.platform || !credentialForm.value.name.trim() || !credentialForm.value.json.trim()) return ElMessage.warning('请完整填写平台、凭据名称和 JSON') ; let parsed: Record<string, unknown>; try { parsed = JSON.parse(credentialForm.value.json) } catch { return ElMessage.error('凭据 JSON 格式无效') } savingCredential.value = true; try { await contentApi.createCredential({ workspace_id: workspaceId, platform: credentialForm.value.platform, name: credentialForm.value.name.trim(), credential_hint: credentialForm.value.hint.trim() || undefined, credentials: parsed as Record<string, string> }); credentialDialog.value = false; credentialForm.value = { platform: '', name: '', hint: '', json: '' }; ElMessage.success('凭据已加密保存'); await load() } catch (error) { ElMessage.error(error instanceof Error ? error.message : '凭据保存失败') } finally { savingCredential.value = false } }
async function load() { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId) return; loading.value = true; const results = await Promise.allSettled([dataCenterApi.overview(workspaceId), contentApi.listPublishes(workspaceId), contentApi.listMetrics(workspaceId), contentApi.listConnectors(), contentApi.listCredentials(workspaceId), contentApi.listMetricSync(workspaceId)]); const [overviewResult, publishResult, metricResult, connectorResult, credentialResult, syncResult] = results; overview.value = overviewResult.status === 'fulfilled' ? overviewResult.value : null; publishes.value = publishResult.status === 'fulfilled' ? publishResult.value.items || [] : []; metrics.value = metricResult.status === 'fulfilled' ? metricResult.value.items || [] : []; connectors.value = connectorResult.status === 'fulfilled' ? connectorResult.value || [] : []; credentials.value = credentialResult.status === 'fulfilled' ? credentialResult.value || [] : []; syncRuns.value = syncResult.status === 'fulfilled' ? syncResult.value.items || [] : []; if (results.some(result => result.status === 'rejected')) ElMessage.warning('部分平台数据暂时不可用，已保留可加载内容'); loading.value = false }
onMounted(async () => { await workspaceStore.fetchCurrentWorkspace(); await completeXOAuthFromQuery(); await load() })
</script>

